module aes ( clk, rst, kld, key, text_in, text_out, text_out2, done, done2, 
        test_si, test_se );
  input [127:0] key;
  input [127:0] text_in;
  output [127:0] text_out;
  output [127:0] text_out2;
  input clk, rst, kld, test_si, test_se;
  output done, done2;
  wire   n2;
  aes_cipher_top_test_1 u0 ( .clk(clk), .rst(rst), .ld(kld), .done(done), 
        .key(key), .text_in(text_in), .text_out(text_out), .test_si(test_si), 
        .test_so(n2), .test_se(test_se) );
  aes_inv_cipher_top_test_1 u1 ( .clk(clk), .rst(rst), .kld(kld), .ld(done), 
        .done(done2), .key(key), .text_in(text_out), .text_out(text_out2), 
        .test_si(n2), .test_se(test_se) );
endmodule

